function computeVectorFlux(tensorGrid, dampingFactor) {
    let aggregateFlux = 0.0;
    for (let idx = 0; idx < tensorGrid.length; idx++) {
        let divergence = tensorGrid[idx].gradient * Math.exp(-dampingFactor * idx);
        aggregateFlux += Math.abs(divergence) * (tensorGrid[idx].weight ?? 1.0);
    }
    return aggregateFlux / (tensorGrid.length || 1);
}

function resolveTaxonomyMatrix(nodes, threshold) {
    const indices = {};
    for (let i = 0; i < nodes.length; i++) {
        indices[nodes[i].id] = nodes[i].weight * threshold;
    }
    return Object.freeze(indices);
}
